633	+/** An intel message as the room delivers it: one of §2 and §5's reveals, or a lead for the player's journal. */
634	+export type DeliveredIntel = { readonly channel: "reveal"; readonly message: RevealMessage } | { readonly channel: "journal"; readonly message: JournalMessage };
635	+
636	+/**
637	+ * Every intel message kind, as the message the room sends. Each field is copied by name, so nothing the intel module
638	+ * might add to a body (an id, a position) rides along; the protocol's strict schemas say the same on the client.
639	+ */
640	+export function intelMessageOf(body: IntelMessageBody): DeliveredIntel {
641	+  switch (body.kind) {
642	+    case "final-sector":
643	+      return { channel: "reveal", message: { kind: body.kind, tick: body.tick, sector: body.sector, name: body.name } };
644	+    case "final-route":
645	+      return { channel: "reveal", message: { kind: body.kind, tick: body.tick, x: body.x, y: body.y, restored: body.restored } };
646	+    case "final-route-inactive":
647	+      return { channel: "reveal", message: { kind: body.kind, tick: body.tick } };
648	+    case "sector-reveal":
649	+      return {
650	+        channel: "reveal",
651	+        message: {
652	+          kind: body.kind,
653	+          tick: body.tick,
654	+          sources: body.sources.map(({ sector, name }) => ({ sector, name })),
655	+          caches: body.caches.map(({ sector, name }) => ({ sector, name })),
656	+        },
657	+      };
658	+    case "carrier-report":
659	+      return {
660	+        channel: "reveal",
661	+        message: { kind: body.kind, tick: body.tick, seenTick: body.seenTick, carriers: body.carriers.map(({ sector, name, type }) => ({ sector, name, type })) },
662	+      };
663	+    case "rumor": {
664	+      const target = body.target;
665	+      return {
666	+        channel: "journal",
667	+        message: {
668	+          kind: body.kind,
669	+          tick: body.tick,
670	+          entry: body.entry,
671	+          type: body.type,
672	+          reason: body.reason,
673	+          target: target.kind === "island" ? { kind: "island", island: target.island, name: target.name } : { kind: "sector", sector: target.sector, name: target.name },
674	+        },
675	+      };
676	+    }
677	+    case "carrier-sighting":
678	+      return {
679	+        channel: "journal",
680	+        message: {
681	+          kind: body.kind,
682	+          tick: body.tick,
683	+          seenTick: body.seenTick,
684	+          sightings: body.sightings.map(({ type, reason, sector, name }) => ({ type, reason, sector, name })),
685	+        },
686	+      };
687	+    case "no-lead":
688	+      return { channel: "journal", message: { kind: body.kind, tick: body.tick, type: body.type, reason: body.reason } };
689	+    case "rumor-stale":
690	+    case "rumor-resolved":
691	+      return { channel: "journal", message: { kind: body.kind, tick: body.tick, entry: body.entry, type: body.type } };
