712	+ */
713	+export class JournalLog {
714	+  private readonly logs = new Map<string, PlayerLog>();
715	+
716	+  private logOf(playerId: string): PlayerLog {
717	+    let log = this.logs.get(playerId);
718	+    if (log === undefined) {
