725	+  /** One lead or notice this player received. */
726	+  record(playerId: string, message: JournalMessage): void {
727	+    const log = this.logOf(playerId);
728	+    switch (message.kind) {
729	+      case "rumor": {
730	+        const target = message.target;
731	+        this.add(log, message.type, message.entry, {
732	+          kind: target.kind,
