1980	+      text.textContent = rumor.text;
1981	+      const reason = document.createElement("em");
1982	+      reason.className = "reason";
1983	+      reason.textContent = rumor.reason;
1984	+      const status = document.createElement("span");
1985	+      status.className = "status";
1986	+      status.textContent = rumor.statusText;
1987	+      const replaced = document.createElement("small");
1988	+      replaced.textContent = rumor.replaced;
1989	+      li.append(text, " ", reason, status, replaced);
1990	+      return li;
1991	+    }),
1992	+  );
1993	+  field(root, "journal-islands").replaceChildren(...view.islands.map((line) => item(line.text, line.state)));
1994	+  field(root, "journal-collected").textContent = view.collected;
1995	+  field(root, "journal-kit").textContent = view.kit.name;
1996	+  field(root, "journal-kit-specials").textContent = view.kit.specials.join(" · ");
1997	+  field(root, "journal-kit-description").textContent = `Advantage: ${view.kit.advantage}. Vulnerability: ${view.kit.vulnerability}.`;
