2004	+    button.dataset["state"] = buy.state;
2005	+    button.textContent = buy.label;
2006	+    button.disabled = buy.disabled;
2007	+    return button;
2008	+  });
2009	+  // The same button elements stay, so focus stays where it is across redraws (20 a second).
2010	+  if (!sameButtons([...existing.keys()], view.buys.map((buy) => buy.type))) buys.replaceChildren(...buttons);
2011	+  const message = field(root, "journal-message");
2012	+  message.textContent = view.message.text;
2013	+  message.dataset["state"] = view.message.state;
