600	   * in an unfinished duel is marked away, the fight going on with their input substituted, and forfeits if still away
601	   * after `duelAbsenceTicks`. Colyseus keeps the socket's seat for the outer bound only.
602	   */
603	  override onDrop(client: Client): void {
604	    const id = client.sessionId;
605	    // A request refused in onJoin (a wrong code, a used token) still drops and leaves, but never became a player.
606	    if (findPlayer(this.ledger, id) === undefined) return;
607	    const tick = this.simulation.worldTick;
608	    this.ledgerStep("disconnectPlayer", disconnectPlayer(this.ledger, { playerId: id, tick }));
609	    const duel = this.duelOfSession(id);
610	    const fighting = duel !== undefined && duel.machine.outcome === undefined;
611	    if (fighting) duel.machine.drop(id);
612	    const reconnection = this.allowReconnection(client, this.tuning.reconnectionSeconds);
613	    reconnection.catch(() => undefined);
614	    this.away.set(id, { reconnection, duelAbsentSince: fighting ? tick : undefined });
615	  }
616	
617	  /** The same player is back before the deadline: the same identity, view, ship and rubbings; a fighter resumes. */
618	  override onReconnect(client: Client): void {
619	    const id = client.sessionId;
620	    this.away.delete(id);
621	    this.ledgerStep("reconnectPlayer", reconnectPlayer(this.ledger, { playerId: id, tick: this.simulation.worldTick }));
622	    this.duelOfSession(id)?.machine.reconnect(id);
623	  }
624	
625	  /**
626	   * A player is gone for good. Unless the reservation already expired (the world tick removed them), this is a quit:
627	   * a consented leave, or Colyseus' outer bound closing first. The ledger forfeits a duel in progress and sends the
628	   * rest of their rubbings into a cache at the dock nearest their ship by sea; then the ship leaves.
629	   */
630	  override onLeave(client: Client): void {
631	    const id = client.sessionId;
632	    const player = findPlayer(this.ledger, id);
633	    if (player !== undefined && player.status !== "left") {
634	      this.quit(id);
635	      this.flowReports.push({ kind: "leave", playerId: id });
636	    }
637	    this.removePlayer(id);
638	    client.view?.dispose();
639	    client.view = undefined;
640	    this.mirror();
641	  }
642	
643	  /**
644	   * Test-only (the server's test-placement setting, off by default): puts a player's ship at rest on a navigable tile.
645	   * Visibility follows at once, as after any move.
646	   */
647	  placeShip(sessionId: string, placement: Placement): void {
648	    this.simulation = placeShip(this.config, this.simulation, sessionId, placement);
649	    this.mirror();
650	  }
651	
652	  /** The ship ids a client's view holds, for tests and diagnostics. */
653	  viewedShipIds(sessionId: string): string[] {
654	    const view = this.clients.get(sessionId)?.view;
655	    if (view === undefined) return [];
656	    return [...this.state.ships.values()].filter((ship) => view.has(ship)).map((ship) => ship.id);
657	  }
658	
659	  /** Inputs dropped per client and reason, for tests and diagnostics. */
660	  droppedInputs(sessionId: string): InputGate["dropped"] | undefined {
661	    return this.gates.get(sessionId)?.dropped;
662	  }
663	
664	  /** The encounter rules' state, for tests. */
665	  get encounterState(): EncounterState {
666	    return this.encounters;
667	  }
668	
669	  /** The simulation state, for tests. */
670	  get matchState(): MatchState {
671	    return this.simulation;
672	  }
673	
674	  /** The objective ledger, for tests. */
675	  get ledgerState(): LedgerState {
676	    return this.ledger;
677	  }
678	
679	  /** The match's timings, for tests. */
680	  get timings(): MatchTuning {
681	    return this.tuning;
682	  }
683	
684	  /** Reports the encounter rules refused, for tests (none are expected). */
685	  get refusedDuelReports(): number {
686	    return this.refusedReports;
687	  }
688	
689	  /** Ledger requests the room made and the ledger refused, as "operation: reason", for tests. */
690	  get ledgerRefusals(): readonly string[] {
691	    return this.refusals;
692	  }
693	
694	  /** Invariant violations found after any world tick so far (none are expected), for tests. */
695	  get invariantViolations(): readonly string[] {
696	    return this.violations;
697	  }
698	
699	  /** The duel at sea a player is in (until its lobby leaves their view), for tests and the harness. */
700	  seaDuelDiagnostics(sessionId: string): SeaDuelDiagnostics | undefined {
701	    const duel = this.duelOfSession(sessionId);
702	    if (duel === undefined) return undefined;
703	    const [a, b] = duel.machine.state.fighters;
704	    return {
705	      ...duel.machine.diagnostics(),
706	      id: duel.id,
707	      outcome: duel.machine.outcome,
708	      players: duel.players,
709	      seed: duel.lobby.seed,
710	      kits: [a.kit, b.kit],
711	      inputLog: duel.machine.authority.inputLog(),
712	    };
713	  }
714	
715	  private admit(options: unknown): void {
716	    this.createToken = admitSeat(options, { code: this.state.code, createToken: this.createToken }, MATCH_ADMISSION);
717	  }
718	
719	  /** Applies a ledger step, and remembers a refusal (the room checks before it asks, so none are expected). */
720	  private ledgerStep<R extends { readonly ok: boolean; readonly rejection: string | null }>(operation: string, stepped: { state: LedgerState; result: R }): R {
721	    this.ledger = stepped.state;
722	    if (!stepped.result.ok) this.refusals.push(`${operation}: ${stepped.result.rejection}`);
723	    return stepped.result;
724	  }
725	
726	  /**
727	   * One frame of the room's clock (60 Hz). Ships sail only while the match runs (§2: player control starts after the
728	   * ready countdown and stops at the end); before and after, every helm is neutral. On every third frame the world
729	   * tick runs in §5's order (`worldTick`), and a fault inside it aborts the match (§12).
730	   */
731	  private advance(): void {
732	    if (this.paused) return;
733	    this.stepFrame();
734	  }
735	
736	  /** One frame of the clock, whether or not the test-only pause holds it (`stepWorldTicks` runs it then). */
737	  private stepFrame(): void {
738	    const frame = this.simulation.frame + 1;
739	    const inputs: Record<string, PlayerInput> = {};
740	    const playing = this.inPlay();
741	    const held = this.heldPlayers();
742	    for (const [sessionId, gate] of this.gates) {
743	      // No control before the start or after the end; a reserved or respawning ship ignores its player's helm (§6).
744	      if (!playing || held.has(sessionId)) inputs[sessionId] = NEUTRAL_INPUT;
745	      // A lapsed client gets no entry: its ship sails as neutral, but keeps its mooring throttle until real input.
746	      else if (!gate.lapsedAt(frame)) inputs[sessionId] = gate.inputAt(frame);
747	    }
748	    this.simulation = step(this.config, this.simulation, inputs);
749	    for (const duel of this.seaDuels.values()) duel.machine.advance();
750	    if (!isWorldStep(this.simulation.frame)) return;
751	    const tick = this.simulation.worldTick;
752	    try {
753	      this.worldTick(frame, tick, held, playing);
754	    } catch (error) {
755	      this.fault(tick, error);
756	    }
757	    for (const gate of this.gates.values()) gate.worldStepTaken();
758	    this.checkInvariants(tick);
759	    this.mirror();
760	    if (this.pauseAt !== undefined && tick >= this.pauseAt) {
761	      this.pauseAt = undefined;
762	      this.paused = true;
763	    }
764	  }
765	
766	  /**
767	   * One world tick (20 Hz), in a fixed order. While the match runs: the ledger's clock (closed theft windows settle),
768	   * the §12 timers, then §5's order: the encounters (accepted reservations first), the ledger's holds, the claim
769	   * channel, the match flow (with this tick's claim end and accomplishments), and the reveals. Before control start
770	   * only the timers and the flow run (the lobby and the ready countdown); once the match has ended nothing changes but
771	   * the settled duels' lobbies leaving their fighters' views.
772	   */
773	  private worldTick(frame: number, tick: number, held: ReadonlySet<string>, playing: boolean): void {
774	    if (this.flow.end !== null) {
775	      this.closeShownDuels(tick);
776	      return;
777	    }
778	    if (this.faultNext) {
779	      this.faultNext = false;
780	      throw new Error("test-only fault injected into the world tick");
781	    }
782	    // The ledger's clock first: choice windows that closed settle with the default theft.
783	    this.ledgerStep("advanceLedger", advanceLedger(this.ledger, { tick }));
784	    this.runAbsences(tick);
785	    let claimEnd: FlowReport | undefined;
786	    if (playing) {
787	      this.stepEncounters(frame, held);
788	      // Where everyone is now, for the ruins: casting off or entering a duel closes a session (§3).
789	      for (const ship of this.simulation.ships) this.syncRuinPresence(ship.id);
790	      // §9's eating, with this tick's reservations: a duel reserved on this tick interrupts it.
791	      this.stepFruits(frame, tick);
792	      this.stepChannels(frame, tick);
793	      claimEnd = this.stepClaim(frame, tick);
794	    }
795	    this.noteSettlements();
796	    if (playing) this.reportAccomplishments(tick);
797	    this.stepFlow(tick, claimEnd);
798	    if (this.flow.controlStartTick !== null && this.flow.end === null) this.stepReveals(tick);
799	  }
800	
801	  /** Player control has started and the match has not ended (§2's departure and exploration). */
802	  private inPlay(): boolean {
803	    return this.flow.phase === "departure" || this.flow.phase === "exploration";
804	  }
805	
806	  /** Players whose ship is reserved for a duel (until it is settled) or waits out of the world to respawn. */
807	  private heldPlayers(): Set<string> {
808	    const held = new Set<string>();
809	    for (const duel of this.encounters.duels) for (const id of duel.players) held.add(id);
810	    for (const player of this.encounters.players) if (player.respawn !== null) held.add(player.id);
811	    return held;
812	  }
813	
814	  /** The duel at sea a session fights in (until its lobby is removed). */
815	  private duelOfSession(sessionId: string): SeaDuel | undefined {
816	    for (const duel of this.seaDuels.values()) if (duel.players.includes(sessionId)) return duel;
817	    return undefined;
818	  }
819	
820	  /** Takes a settled duel's lobby out of its fighters' views. */
821	  private closeSeaDuel(duel: SeaDuel): void {
822	    this.state.duels.delete(duel.key);
823	    this.seaDuels.delete(duel.id);
824	  }
825	
826	  /**
827	   * §12 on the world tick: a fighter away from an unfinished duel for `duelAbsenceTicks` forfeits it (the duel goes on
828	   * to its settlement; they keep their seat); a disconnected player whose reservation deadline has come is removed,
829	   * their remaining rubbings going into a cache at the respawn dock the encounter rules would choose.
830	   */
831	  private runAbsences(tick: number): void {
832	    for (const [id, away] of this.away) {
833	      if (away.duelAbsentSince === undefined) continue;
834	      const duel = this.duelOfSession(id);
835	      if (duel === undefined || duel.machine.outcome !== undefined) away.duelAbsentSince = undefined;
836	      else if (tick - away.duelAbsentSince >= this.tuning.duelAbsenceTicks) {
837	        duel.machine.leave(id);
838	        away.duelAbsentSince = undefined;
839	      }
840	    }
841	    for (const player of this.ledger.players) {
842	      if (player.status !== "disconnected" || player.reservationDeadline === null || tick < player.reservationDeadline) continue;
843	      const position = this.respawnDockOf(player.id);
844	      this.ledgerStep("expireReservation", expireReservation(this.ledger, { playerId: player.id, tick, position }));
845	      // §12: an expired reservation releases the seat, which the flow counts as leaving.
